const cy = game.everglades.parts.cypress; const T = game.THREE; let best = null; const ts = cy.treesNear(s.at[0], s.at[1], 900); for (const t of ts) { const d = Math.hypot(t.x - s.at[0], t.z - s.at[1]); if (!best || d < best.d) best = { t, d }; } if (!best) return 'no tree'; const t = best.t, a = s.az || 0.7, D = s.dist || 34;
 const eye = new T.Vector3(t.x + Math.cos(a) * D, t.y + (s.eh || 2), t.z + Math.sin(a) * D), look = new T.Vector3(t.x, t.y + t.H * (s.lh || 0.45), t.z); game.teleport(eye.x, undefined, eye.z, 0);
 game.cameraOverride = (dt, cam) => { cam.position.copy(eye); cam.lookAt(look); if (cam.fov !== 60) { cam.fov = 60; cam.updateProjectionMatrix(); } return true; }; window.__vegShotCam = [eye.toArray(), look.toArray()]; await new Promise((r) => setTimeout(r, 6000)); return { x: t.x, z: t.z, H: t.H, n: ts.length };

